@layer components {
  /* Icon: a box of the icon size. The SVG in it fills the box and takes the text color. */
  [data-slot="icon"] {
    align-items: center;
    display: inline-flex;
    flex: none;
    height: 1rem;
    justify-content: center;
    width: 1rem;
  }

  [data-slot="icon"][data-size="xs"] {
    height: 0.75rem;
    width: 0.75rem;
  }

  [data-slot="icon"][data-size="sm"] {
    height: 0.875rem;
    width: 0.875rem;
  }

  [data-slot="icon"][data-size="lg"] {
    height: 1.25rem;
    width: 1.25rem;
  }

  [data-slot="icon"] > svg {
    height: 100%;
    width: 100%;
  }
}

export type IconSize = "xs" | "sm" | "md" | "lg";

export interface IconProps {
  size?: IconSize;
  label?: string;
}

export interface IconSlots {
  default?: () => unknown;
}
